D={
81279:("make × do","**Make** = criar (*a deposit, a call, money*). **Do** = tarefa (*paperwork, a form, homework*).",[("I want to {{make}} a deposit.","Quero fazer um depósito."),("Please {{do}} the form.","Por favor, preencha o formulário."),("I want to {{open}} an account.","Quero abrir uma conta."),("I need to {{make}} a call.","Preciso fazer uma ligação.")],"Qual combina com “homework”?",["make","do","get"],1,"Do homework."),
81280:("Ordens urgentes","Em emergência, frases curtas no **imperativo**: *Call 911! Stay calm. Hurry, please!*",[("Please {{send}} an ambulance.","Por favor, mande uma ambulância."),("{{Stay calm}}.","Fique calmo."),("{{Call}} 911!","Ligue para o 911!"),("{{Hurry}}, please!","Rápido, por favor!")],"Qual é uma ordem curta?",["Stay calm.","You are staying.","Calm is staying."],0,"Imperativo = verbo sozinho."),
920040:("with / without / by","**With** = com; **without** = sem; **by** = meio de transporte.",[("I cut it {{with}} sticks.","Cortei com gravetos."),("I live {{without}} a friend.","Vivo sem um amigo."),("I travel {{by}} bus.","Viajo de ônibus."),("We sail {{by}} boat.","Navegamos de barco.")],"Complete: “I go to work ___ bus.”",["with","by","in"],1,"Transporte: by."),
81282:("hope to / want to / plan to","Metas: **hope to**, **want to**, **plan to** + verbo.",[("I {{hope to}} travel one day.","Espero viajar um dia."),("I {{want to}} be free.","Quero ser livre."),("We {{plan to}} work together.","Planejamos trabalhar juntos."),("She {{hopes to}} learn Spanish.","Ela espera aprender espanhol.")],"Qual está certa?",["I plan study.","I plan to study.","I plan studying."],1,"Plan to + verbo."),
81283:("Simples × contínuo","**Presente simples** = hábito; **contínuo** (am/is/are + -ing) = agora.",[("I {{usually walk}} to work.","Geralmente vou a pé ao trabalho."),("I {{am taking}} the bus today.","Hoje estou indo de ônibus."),("She {{always smiles}}.","Ela sempre sorri."),("Right {{now}}, it is raining.","Agora mesmo, está chovendo.")],"“Today” combina com…",["presente simples","presente contínuo","passado"],1,"Hoje, agora: -ing."),
81284:("Frações","**Half** = ½; **a quarter** = ¼; **a third** = ⅓. *Fifty percent = half.*",[("I ate {{half}} of the pizza.","Comi metade da pizza."),("A {{quarter}} is twenty-five percent.","Um quarto é vinte e cinco por cento."),("{{Fifty percent}} is half.","Cinquenta por cento é metade."),("A {{third}} is left.","Sobrou um terço.")],"Quanto é “a quarter”?",["½","¼","⅓"],1,"Quarter = ¼."),
81285:("How + adjetivo","Medidas: **How tall…? How long…? How heavy…?**",[("{{How tall}} are you?","Qual é a sua altura?"),("{{How long}} is the table?","Qual é o comprimento da mesa?"),("It is two meters {{long}}.","Tem dois metros de comprimento."),("{{How heavy}} is the box?","Quanto pesa a caixa?")],"Como perguntar a altura?",["How tall are you?","How high you are?","What tall?"],0,"How tall."),
81286:("ago / just / lately","**Ago** + passado; **just** = acabou de; **recently / lately** = há pouco tempo.",[("I met her two years {{ago}}.","Conheci-a há dois anos."),("I have {{just}} arrived.","Acabei de chegar."),("I have been busy {{lately}}.","Tenho andado ocupado ultimamente."),("{{Recently}}, I moved.","Recentemente, me mudei.")],"“I have just arrived” quer dizer…",["Cheguei há muito tempo.","Acabei de chegar.","Vou chegar."],1,"Just = acabou de."),
920041:("E-mails simples","**Dear** e **Best regards** são formais; **Hi** e **Thanks** são informais.",[("{{Dear}} Sam,","Caro Sam,"),("Please {{see}} the file.","Veja o arquivo, por favor."),("{{Best regards}},","Atenciosamente,"),("{{Hi}} Sam, thanks!","Oi, Sam, obrigado!")],"Qual é formal?",["Hey!","Dear Mr. Lee,","Yo!"],1,"Dear + sobrenome é formal."),
81288:("would like / Can I have","Pedir com educação: **I would like…** ou **Can I have…?**",[("{{I would like}} a taco, please.","Gostaria de um taco, por favor."),("{{Can I have}} a napkin?","Posso ter um guardanapo?"),("{{Is it}} spicy?","É picante?"),("{{I would like}} it fresh.","Gostaria dele fresco.")],"Qual é mais educado?",["I want a taco.","I would like a taco, please.","Taco now."],1,"I would like + please."),
81289:("Did em perguntas","Pergunta no passado: **Did + sujeito + verbo base**. Resposta: *Yes, I did. / No, I didn't.*",[("{{Did you like}} the food?","Você gostou da comida?"),("Yes, I {{did}}.","Sim, gostei."),("{{What did you eat}}?","O que você comeu?"),("{{Did the waiter help}} you?","O garçom ajudou você?")],"Qual está certa?",["Did you liked it?","Did you like it?","Do you liked it?"],1,"Did + verbo base."),
81290:("more / less / fewer","**More** = mais; **less** + incontável; **fewer** + contável.",[("Eat {{more}} vegetables.","Coma mais legumes."),("Eat {{less}} sugar.","Coma menos açúcar."),("Eat {{fewer}} burgers.","Coma menos hambúrgueres."),("Drink {{less}} soda.","Beba menos refrigerante.")],"Complete: “fewer ___” (contável)",["sugar","apples","water"],1,"Apples se contam: fewer."),
81291:("Nacionalidades","Nacionalidades são **adjetivos** e começam com **maiúscula**.",[("I love {{Italian}} pasta.","Adoro massa italiana."),("I am {{Brazilian}}.","Sou brasileiro."),("{{Where are you from}}?","De onde você é?"),("We ate {{Japanese}} sushi.","Comemos sushi japonês.")],"Qual está certa?",["italian pasta","Italian pasta","Italy pasta"],1,"Maiúscula: Italian."),
81293:("first, then, next, finally","Para contar a ordem: **first, then, next, finally**.",[("{{First}}, we visit the museum.","Primeiro, visitamos o museu."),("{{Then}}, we have lunch.","Depois, almoçamos."),("{{Next}}, we take a boat tour.","Em seguida, fazemos um passeio de barco."),("{{Finally}}, we watch the sunset.","Por fim, vemos o pôr do sol.")],"Qual vem por último?",["First","Next","Finally"],2,"Finally = por fim."),
920042:("I think / I agree","**I think** e **in my opinion** dão opinião; **I agree / I disagree** reagem.",[("{{I think}} it is good.","Acho que é bom."),("{{In my opinion}}, he is right.","Na minha opinião, ele tem razão."),("{{I agree}} with you.","Concordo com você."),("{{I disagree}}. It is too long.","Discordo. É longo demais.")],"Qual reage discordando?",["I agree.","I disagree.","I think."],1,"Disagree."),
81295:("How long / How far","**How long** = tempo; **how far** = distância.",[("{{How long}} does it take?","Quanto tempo leva?"),("{{How far}} is the temple?","A que distância fica o templo?"),("It {{takes}} two hours.","Leva duas horas."),("It is ten kilometers {{away}}.","Fica a dez quilômetros.")],"“How far?” pergunta…",["o tempo","a distância","o preço"],1,"Far = distância."),
81296:("Comparativos","Curto + **-er than**; terminado em -y: *noisy → noisier*; longo: **more**.",[("New York is {{bigger than}} Boston.","Nova York é maior que Boston."),("Downtown is {{noisier than}} my street.","O centro é mais barulhento que minha rua."),("This area is {{safer than}} that one.","Esta área é mais segura que aquela."),("It is {{more crowded}}.","É mais lotado.")],"Qual é o comparativo de “busy”?",["busyer","busier","more busy"],1,"y vira ier."),
81298:("Let's / Why don't we","Sugestões: **Let's + verbo** ou **Why don't we + verbo?**",[("{{Let's watch}} the parade.","Vamos ver o desfile."),("{{Why don't we buy}} a gift?","Por que não compramos um presente?"),("On Thanksgiving we {{eat}} turkey.","No Dia de Ação de Graças comemos peru."),("{{Let's celebrate}}!","Vamos comemorar!")],"Qual é uma sugestão?",["Let's go!","We go let's.","Let go!"],0,"Let's + verbo."),
81299:("mustn't","**Mustn't + verbo** = é proibido. *You mustn't be late.*",[("You {{mustn't be}} late.","Você não pode se atrasar."),("Students {{mustn't use}} phones in class.","Alunos não podem usar celular na aula."),("You {{must do}} your homework.","Você deve fazer a lição."),("You {{mustn't}} run in the hall.","Você não pode correr no corredor.")],"“You mustn't” significa…",["você pode","é proibido","não precisa"],1,"Mustn't = proibido."),
81300:("should","Conselho: **should + verbo base**, sem -s.",[("We {{should recycle}} paper.","Deveríamos reciclar papel."),("We {{shouldn't make}} so much waste.","Não deveríamos gerar tanto lixo."),("{{What should we do}}?","O que devemos fazer?"),("She {{should}} save energy.","Ela deveria economizar energia.")],"Qual está certa?",["She shoulds go.","She should go.","She should goes."],1,"Should + verbo base."),
81301:("somebody / anybody / nobody","**Somebody** (afirmativa); **anybody** (pergunta, negativa); **nobody** = ninguém.",[("{{Somebody}} is at the door.","Alguém está na porta."),("Is {{anybody}} at home?","Tem alguém em casa?"),("{{Nobody}} is in the street.","Ninguém está na rua."),("I don't see {{anybody}}.","Não vejo ninguém.")],"Complete: “Is ___ here?”",["somebody","anybody","nobody"],1,"Pergunta: anybody."),
920043:("Can I / Shall I","Oferecer ajuda: **Can I…? Shall I…? Let me…** Resposta: *Yes, please. / No, thanks.*",[("{{Can I help}} you?","Posso ajudá-lo?"),("{{Shall I open}} the door?","Devo abrir a porta?"),("{{Let me help}} with the door.","Deixe-me ajudar com a porta."),("{{Yes, please}}. Thanks!","Sim, por favor. Obrigado!")],"Qual oferece ajuda?",["Shall I carry it?","I carry shall?","Carry I?"],0,"Shall I + verbo."),
81302:("Pedir para repetir","**Could you repeat that? Please speak slowly. I don't understand.**",[("{{Could you repeat that}}?","Você poderia repetir?"),("Please {{speak slowly}}.","Por favor, fale devagar."),("{{I don't understand}}.","Não entendi."),("{{What do you mean}}?","O que você quer dizer?")],"Qual pede para repetir?",["Could you repeat that?","Can you forget that?","I mean that."],0,"Repeat = repetir."),
81303:("cheaper than","Comparar preços: **-er than** (curtos) e **more … than** (longos).",[("This coat is {{cheaper than}} that one.","Este casaco é mais barato que aquele."),("That coat is {{more expensive than}} this one.","Aquele casaco é mais caro que este."),("{{Is there}} a discount?","Há desconto?"),("This is {{on sale}}.","Está em promoção.")],"Qual está certa?",["more cheap than","cheaper than","cheapest than"],1,"Cheap → cheaper."),
81304:("Convites","Convidar: **Are you free…? Would you like to…?** Aceitar: *Sure! / I'd love to.* Recusar: *Sorry, I'm busy.*",[("{{Are you free}} on Saturday?","Você está livre no sábado?"),("{{Would you like to}} have dinner?","Gostaria de jantar?"),("{{Sorry, I am busy}}.","Desculpe, estou ocupado."),("{{I'd love to}}!","Adoraria!")],"Como aceitar?",["Sure!","Sorry, I'm busy.","No way."],0,"Sure! aceita."),
81305:("have just + particípio","**Have/has just + particípio** = acabou de.",[("I {{have just read}} your message.","Acabei de ler sua mensagem."),("She {{has just called}}.","Ela acabou de ligar."),("{{Unfortunately}}, I can't come.","Infelizmente, não posso ir."),("Can we {{reschedule}} for Friday?","Podemos remarcar para sexta?")],"Complete: “She ___ just left.”",["have","has","is"],1,"She: has."),
81306:("No + -ing","Placas de proibição: **No + verbo-ing**.",[("{{No smoking}}.","Proibido fumar."),("{{No parking}}.","Proibido estacionar."),("The {{entrance}} is on the left.","A entrada fica à esquerda."),("The {{exit}} is on the right.","A saída fica à direita.")],"“No running” significa…",["corra","é proibido correr","pode correr"],1,"No + -ing = proibido."),
81307:("Shall I / I'll","Oferecer ajuda: **Shall I + verbo?** ou **I'll + verbo**.",[("{{Shall I carry}} your bag?","Devo carregar sua bolsa?"),("{{I'll open}} the door.","Eu abro a porta."),("{{Could you do me a favor}}?","Você poderia me fazer um favor?"),("{{I'll give}} you a ride.","Dou uma carona a você.")],"“I'll” é a forma curta de…",["I will","I shall not","I all"],0,"I'll = I will."),
81308:("been × gone","**Been to** = foi e voltou; **gone to** = foi e ainda está lá.",[("I have {{been to}} Paris.","Já estive em Paris."),("She has {{gone to}} Paris.","Ela foi a Paris (ainda está lá)."),("She {{will be back}} on Friday.","Ela volta na sexta."),("He has {{been}} away.","Ele esteve fora.")],"“She has gone to Rome” — ela está…",["em casa","em Roma","a caminho de casa"],1,"Gone = ainda lá."),
920044:("No aeroporto","Perguntas úteis: **Where is…? Which gate…? May I see…?**",[("{{Where is}} the gate, please?","Onde fica o portão, por favor?"),("{{Which gate}} is it?","Qual é o portão?"),("{{May I see}} your ticket?","Posso ver sua passagem?"),("I'd like an {{aisle seat}}.","Gostaria de um assento no corredor.")],"“Which gate?” pergunta…",["o horário","o portão","o preço"],1,"Gate = portão."),
81309:("this / that / these / those","**This/these** = perto; **that/those** = longe.",[("{{This}} toy is old.","Este brinquedo é velho."),("{{These}} boxes are heavy.","Estas caixas são pesadas."),("{{That}} cowboy is my favorite.","Aquele cowboy é meu favorito."),("{{Those}} books are one dollar.","Aqueles livros custam um dólar.")],"Complete: “___ shoes there are cheap.” (longe)",["These","Those","This"],1,"Longe, plural: those."),
81310:("Quantidades","**A pound of, a dozen, a bag of**. Vago: *some, a little, a few*.",[("{{A pound of}} apples, please.","Uma libra de maçãs, por favor."),("{{A dozen}} eggs, please.","Uma dúzia de ovos, por favor."),("{{How much}} fruit do you want?","Quanta fruta você quer?"),("{{A bag of}} oranges.","Um saco de laranjas.")],"“A dozen” é…",["6","12","20"],1,"Dozen = 12."),
81311:("one / ones","**One** evita repetir um singular; **ones** o plural.",[("I'll have the big burger, not the small {{one}}.","Quero o hambúrguer grande, não o pequeno."),("I'd like the large fries, not the small {{ones}}.","Quero as fritas grandes, não as pequenas."),("{{Which one}} do you want?","Qual você quer?"),("The red {{one}}, please.","O vermelho, por favor.")],"Complete: “I like the blue ___.” (vários)",["one","ones","a"],1,"Plural: ones."),
81312:("when / as soon as","Depois de **when** e **as soon as**, use o **presente** para o futuro.",[("{{When}} the driver comes, I'll pay.","Quando o motoboy chegar, eu pago."),("I'll eat {{as soon as}} it arrives.","Comerei assim que chegar."),("{{When will}} it arrive?","Quando vai chegar?"),("{{As soon as}} I get home, I'll call.","Assim que chegar em casa, ligo.")],"Qual está certa?",["When he will come, I pay.","When he comes, I'll pay.","When he comes, I paid."],1,"When + presente."),
81313:("between / behind / opposite","**Between** = entre; **behind** = atrás; **in front of** = na frente; **opposite** = do outro lado.",[("The bakery is {{between}} the bank and the shop.","A padaria fica entre o banco e a loja."),("The park is {{behind}} the school.","O parque fica atrás da escola."),("The bank is {{opposite}} the park.","O banco fica em frente ao parque."),("It's {{in front of}} the station.","Fica na frente da estação.")],"“Behind” significa…",["na frente","atrás","entre"],1,"Behind = atrás."),
81314:("news + present perfect","*News* é incontável (*The news is good*). Novidade recente: **present perfect**.",[("I {{have}} good news.","Tenho boas notícias."),("I {{have caught}} a big fish.","Peguei um peixe grande."),("{{Guess}} what happened!","Adivinha o que aconteceu!"),("The news {{is}} great.","A notícia é ótima.")],"Qual está certa?",["The news are good.","The news is good.","The newses are good."],1,"News é singular: is."),
81315:("worried about","**Worried about** + nome/-ing; **afraid of**; **nervous about**.",[("I am {{worried about}} the exam.","Estou preocupado com a prova."),("He is {{afraid of}} the dark.","Ele tem medo do escuro."),("I feel {{nervous about}} the trip.","Fico nervoso com a viagem."),("Stay {{calm}}.","Fique calmo.")],"Complete: “She is afraid ___ spiders.”",["of","about","for"],0,"Afraid of."),
}
